examples.code:
#include <ranges>
#include <sstream>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::istringstream input{"2 3"};
    auto view = std::ranges::istream_view<int>(input);
    auto position = view.begin();
    assert(*position == 2);
    ++position;
    assert(*position == 3);
    ++position;
    assert(position == view.end());
}
